    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Adaptive Slivers Penalty: Penalize residuals that are too small to hold common sizes.
    // Using non-linear scaling for sub-15 residuals to force tighter fits.
    if post_residual > 0 && post_residual < 15 {
        score += 55.0 + (15.0 - post_residual as f64) * 4.5;
    }

    // 2. Lookahead Coupling: Reward bins that can accommodate the next item.
    // Enhanced to favor bins that leave an even tighter residual after the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 75.0; 
        score -= (1.0 / (after_next as f64 + 1.0)) * 20.0;
    }

    // 3. Global State Balancing: Dynamic thresholding for new bin creation.
    // If we have many open bins, we must be more aggressive in filling existing ones.
    if is_new_bin {
        let base_new_bin_cost = 40.0;
        let congestion_penalty = (open_bins_count as f64 / (total_items as f64 * 0.05).max(1.0)) * 10.0;
        score += base_new_bin_cost + (mean_residual * 0.9) + congestion_penalty;
    } else {
        // 4. Fitting Constraint: Strong preference for existing bins that are "bottlenecks"
        if fitting_bins_count == 1 {
            score -= 65.0;
        }
    }

    // 5. Progression Scaling: Entropy reduction towards end of stream.
    // Penalize large residuals more heavily as the stream terminates to prevent trailing empty space.
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    // 6. Tightness Bias: Standard Best Fit logic with a slight boost for high-density configurations.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    score
