        }
        score += new_bin_cost;
    }

    // 4. Residual Variance Smoothing
    // Penalize residuals that deviate significantly from the global mean to promote uniform packing
    let residual_diff = (post_residual as f64) - mean_residual;
    score += residual_diff * 1.8;

