    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Nonlinear Penalty for "Sliver" creation (wasted space < 12)
    // Adjusted: Exponentially penalize small gaps that prevent future placement
    if post_residual > 0 && post_residual < 12 {
        score += (14.0 - post_residual as f64).powi(2) * 4.5;
    }

    // 2. Lookahead Logic: Anticipate next_item_size with higher weight
    // If we can fit the next item, we prioritize that bin to maximize bin utility
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 12.0;
            if post_residual == next_item_size {
                score -= 85.0; // Perfect fit bonus
            }
        }
    }

    // 3. Dynamic New-Bin Thresholding
    if is_new_bin {
        // Base penalty to open new bins, increasing with progress to force consolidation
        score += 110.0 + (progress * 50.0);

        // If we have existing bins that can fit, make the new bin extremely unattractive
        if fitting_bins_count > 0 {
            score += 200.0;
        }
    } else {
        // 4. Tightness Bias: Reward bins that stay below the mean residual
        // Penalize bins that are "too empty" relative to the current average
