    // Penalize higher total occupancy as the stream progresses to minimize the bin count.
    // We emphasize the "Best Fit" aspect by slightly favoring lower post_residuals.
    score += (bin_capacity - post_residual) as f64 * (0.1 + (progress * 0.3));

    score
